import { WALLET_CONFIG } from "@/constants/wallet";
import type { JsonRpcSigner } from "@ethersproject/providers";
import type { ethers } from "ethers";
import { useCallback } from "react";
import { Client, Presets } from "userop";

export type BuilderConfig = {
  rpcUrl: string;
  bundlerUrl?: string;
  entryPoint?: string;
  accountFactory?: string;
  paymasterApi?: string;
  paymasterUrl?: string;
};

export type PaymasterOptions = {
  apikey?: string;
  rpc?: string;
  type?: number;    // 0 = sponsored, 1+ = ERC-20
  token?: string;   // ERC-20 address for type 1+
};

export const useBuilderWithPaymaster = (
  signer?: ethers.Signer | JsonRpcSigner,
  config?: BuilderConfig,
) => {
  const initBuilder = useCallback(
    async (usePaymaster: boolean, paymasterTokenAddress?: string, type = 0) => {
      const cfg = config ?? WALLET_CONFIG;
      if (!signer || !cfg) return undefined;

      const builder = await Presets.Builder.SimpleAccount.init(signer, cfg.rpcUrl, {
        overrideBundlerRpc: cfg.bundlerUrl,
        entryPoint: cfg.entryPoint,
        factory: cfg.accountFactory,
      });

      if (usePaymaster) {
        builder.setPaymasterOptions({
          apikey: cfg.paymasterApi,
          rpc: cfg.paymasterUrl,
          type,
          ...(type !== 0 && paymasterTokenAddress ? { token: paymasterTokenAddress } : {}),
        });
      } else {
        builder.setPaymasterOptions(undefined);
      }
      return builder;
    },
    [signer, config],
  );

  const sendUserOp = useCallback(
    async (builder: Presets.Builder.SimpleAccount, opts?: { dryRun?: boolean }) => {
      const cfg = config ?? WALLET_CONFIG;
      if (!cfg) throw new Error("Config not provided");
      const client = await Client.init(cfg.rpcUrl, {
        overrideBundlerRpc: cfg.bundlerUrl,
        entryPoint: cfg.entryPoint,
      });
      return client.sendUserOperation(builder, opts);
    },
    [config],
  );

  return { initBuilder, sendUserOp };
};

