import { Web3Provider } from "@ethersproject/providers";
import { formatEther, parseEther } from "@ethersproject/units";
import { useWeb3Auth } from "@web3auth/modal/react";
import { ethers } from "ethers";
import { useCallback, useEffect, useState } from "react";
import { useBuilderWithPaymaster, type BuilderConfig } from "@/hooks/useBuilderWithPaymaster";

export const useWallet = (builderConfig: BuilderConfig) => {
  const { web3Auth, isConnected, provider } = useWeb3Auth();
  const [walletAddress, setWalletAddress] = useState<string | null>(null);  // EOA
  const [scwAddress, setScwAddress] = useState<string | null>(null);        // SimpleAccount
  const [ethersSigner, setEthersSigner] = useState<any>();
  const [balance, setBalance] = useState("0.00");
  const [loading, setLoading] = useState(true);
  const [authError, setAuthError] = useState<string | null>(null);

  const { initBuilder, sendUserOp } = useBuilderWithPaymaster(ethersSigner, builderConfig);

  const fetchBalance = useCallback(async (addr: string) => {
    if (!provider) return;
    const web3Provider = new Web3Provider(provider as any);
    const wei = await web3Provider.getBalance(addr);
    setBalance(Number.parseFloat(formatEther(wei)).toFixed(4));
  }, [provider]);

  useEffect(() => {
    (async () => {
      try {
        if (!web3Auth || !provider) return;
        const accounts = (await provider.request({ method: "eth_accounts" })) as string[];
        if (!accounts?.length) return;
        setWalletAddress(accounts[0]);
        setEthersSigner(new Web3Provider(provider as any).getSigner());
      } catch (e) {
        setAuthError(e instanceof Error ? e.message : "unknown");
      } finally {
        setLoading(false);
      }
    })();
  }, [web3Auth, provider]);

  useEffect(() => {
    if (!ethersSigner || scwAddress) return;
    (async () => {
      const builder = await initBuilder(true, undefined, 0);
      const addr = builder?.proxy?.address;
      if (addr) { setScwAddress(addr); fetchBalance(addr); }
    })();
  }, [ethersSigner, scwAddress, initBuilder, fetchBalance]);

  const connect = useCallback(async () => {
    if (!web3Auth) return;
    await web3Auth.connect();
  }, [web3Auth]);

  const disconnect = useCallback(async () => {
    if (!web3Auth) return;
    await web3Auth.logout();
    setWalletAddress(null); setScwAddress(null); setEthersSigner(undefined);
  }, [web3Auth]);

  const send = useCallback(async (to: string, amount: string) => {
    if (!ethersSigner) throw new Error("No signer available");
    const builder = await initBuilder(true, undefined, 0);
    if (!builder) throw new Error("Failed to init builder");
    builder.execute(to, parseEther(amount), "0x");
    const result = await sendUserOp(builder);
    const receipt = await result.wait();
    if (scwAddress) fetchBalance(scwAddress);
    return { userOpHash: result.userOpHash, transactionHash: receipt?.transactionHash ?? "" };
  }, [ethersSigner, initBuilder, sendUserOp, scwAddress, fetchBalance]);

  return {
    state: { isConnected, walletAddress, scwAddress, balance, loading, authError, ethersSigner },
    actions: { connect, disconnect, send, refetchBalance: () => scwAddress && fetchBalance(scwAddress) },
  };
};

