import { ethers } from "ethers";

const ERC20_ABI = [
  "function transfer(address to, uint256 amount) returns (bool)",
  "function approve(address spender, uint256 amount) returns (bool)",
  "function balanceOf(address account) view returns (uint256)",
];

const transferERC20 = async (
  tokenAddress: string,
  to: string,
  amount: string,
  decimals = 18,
) => {
  const builder = await initBuilder(true, undefined, 0);  // Type 0 = sponsored
  if (!builder) throw new Error("Failed to init builder");

  const contract = new ethers.Contract(tokenAddress, ERC20_ABI);
  const amountWei = ethers.parseUnits(amount, decimals);
  const data = contract.interface.encodeFunctionData("transfer", [to, amountWei]);

  builder.execute(tokenAddress, "0", data);
  const result = await sendUserOp(builder);
  return await result.wait();
};

