"use client";
import { WALLET_CONFIG } from "@/constants/wallet";
import { useWallet } from "@/hooks/useWallet";
import { useState } from "react";

export default function WalletPage() {
  const { state, actions } = useWallet(WALLET_CONFIG);
  const [to, setTo] = useState("");
  const [amount, setAmount] = useState("");
  const [sending, setSending] = useState(false);

  if (state.loading) return <div>Loading…</div>;
  if (state.authError) return <div>Error: {state.authError}</div>;

  if (!state.isConnected) {
    return <button onClick={actions.connect}>Connect Wallet</button>;
  }

  const handleSend = async () => {
    if (!to || !amount) return;
    setSending(true);
    try {
      const { transactionHash } = await actions.send(to, amount);
      alert(`Sent! Tx: ${transactionHash}`);
      setTo(""); setAmount("");
    } finally {
      setSending(false);
    }
  };

  return (
    <main>
      <div>Smart Contract Wallet: {state.scwAddress}</div>
      <div>{state.balance} NERO</div>
      <input placeholder="Recipient (0x…)" value={to} onChange={(e) => setTo(e.target.value)} />
      <input type="number" placeholder="Amount" value={amount} onChange={(e) => setAmount(e.target.value)} />
      <button onClick={handleSend} disabled={sending || !to || !amount}>
        {sending ? "Sending…" : "Send (Gasless)"}
      </button>
      <button onClick={actions.refetchBalance}>Refresh</button>
      <button onClick={actions.disconnect}>Disconnect</button>
    </main>
  );
}

