// "No signer available"
//   → web3Auth.connect() hasn't completed; guard with state.isConnected

// "Failed to initialize builder"
//   → check RPC_URL / BUNDLER_URL / EntryPoint address in env

// "Insufficient funds"
//   → SCW has no balance; fund it or switch to Type 0 (sponsored)

// "Paymaster error" / HTTP 401 at paymaster
//   → bad or rotated API key; regenerate at aa-platform.nerochain.io

// -32501 (validatePaymasterUserOp rejected)
//   → sponsorship quota exhausted or project-level token not approved

// -32503 (out of time-range)
//   → rebuild the UserOp and resend; do not reuse old nonces

// -32504 (paymaster throttled)
//   → HTTP 429-class; back off exponentially from 1s, max 3 retries

// Best-effort retry wrapper:
async function withRetry<T>(fn: () => Promise<T>, n = 3): Promise<T> {
  let delay = 1000;
  for (let i = 0; i < n; i++) {
    try { return await fn(); }
    catch (e: any) {
      const code = e?.code ?? e?.error?.code;
      if (!["-32503", "-32504"].includes(String(code)) && code !== 429) throw e;
      if (i === n - 1) throw e;
      await new Promise((r) => setTimeout(r, delay + Math.random() * 500));
      delay *= 2;
    }
  }
  throw new Error("unreachable");
}

